from pathlib import Path
import base64, json
R = Path(__file__).resolve().parents[2]
O = R / 'renders/falaises_proches_metano_v1'
m = json.loads((O / 'manifest.json').read_text())


def uri(p):
    return 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()


data = {'manifest': m,
        'commun': {n: uri(O / 'commun' / (n + '.png')) for n in
                   ['01_ciel_jour', '02_ciel_nuit', '03_mer_jour', '04_mer_nuit',
                    '05_nuages_wrap_jour', '06_nuages_wrap_nuit']},
        'variants': {v['id']: {**v, 'falaise': uri(O / v['id'] / '07_falaise.png'),
                               'falaise_nuit': uri(O / v['id'] / '08_falaise_nuit.png')}
                     for v in m['variants']}}
h = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Falaises proches Métano · mer · ciel · wrap</title><style>*{box-sizing:border-box}body{margin:0;background:#101820;color:#e8f0f8;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#bcc8d8;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#9fd0ff}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #4a6a8a;border-radius:6px;background:#1d2c3e;color:#eef4fc}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#0a1018}aside{background:#17222f;padding:18px;border-radius:8px}label{display:block;margin:12px 0;font-size:14px}a{color:#bcdcff}small{color:#93a5b8}footer{border-top:1px solid #2a3a4e}.anim{display:flex;gap:8px;align-items:center;margin:12px 0;font-size:14px;flex-wrap:wrap}.anim button{padding:8px 12px}input[type=range]{width:120px}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">MÉTANO / FALAISES PROCHES / MER / WRAP</div><h1>Falaises latérales proches caméra · mer · jour/nuit</h1><p>Deux variantes : cap à gauche, terrasse à droite. Ciel jour/nuit, mer en contrebas, famille de nuages en wrap horizontal continu. Falaises générées d’après la matière Métano, nuit au filtre Abyss exact.</p></header><main><div class="toolbar"><select id="room"></select><button id="dn">🌙 Passer en nuit</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="768" height="512"></canvas><div class="anim"><button id="play">⏸ Pause nuages</button><label style="margin:0">vitesse <input type="range" id="speed" min="5" max="120" value="30"> <span id="spd">30px/s</span></label><span id="off">décalage 0px / 630</span></div><p id="status"></p></section><aside><b>Calques</b><div id="layers"></div><small>Ordre : ciel, nuages (wrap), mer, falaise. La falaise proche caméra passe devant les nuages. Période de wrap 630px : boucle parfaite mathématique.</small></aside></div></main><footer><p>Layouts générés séparément (falaise / mer / ciels / nuages), matière guidée par la référence canonique Métano — audit 81–86% dans la palette, pas des pixels natifs certifiés. Nuit = filtre Abyss exact, une passe.</p><small>Bande de mer fixe, pas de cycle de vagues dans ce lot. Ni collisions ni test PMDO.</small></footer><script>const D=__DATA__,c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let vid='cap_gauche',isNight=false,playing=true,off=0,last=0,speed=30;const IM={};function image(src){let im=new Image();im.src=src;return im}for(const [k,v]of Object.entries(D.commun))IM[k]=image(v);for(const [id,e]of Object.entries(D.variants)){IM[id+'_j']=image(e.falaise);IM[id+'_n']=image(e.falaise_nuit);let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}const LAYERS=[['ciel','Ciel'],['nuages','Nuages (wrap)'],['mer','Mer'],['falaise','Falaise']],vis={ciel:true,nuages:true,mer:true,falaise:true};const root=document.getElementById('layers');for(const [k,t]of LAYERS){const l=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.onchange=()=>vis[k]=ch.checked;l.append(ch,document.createTextNode(t));root.append(l)}select.onchange=()=>vid=select.value;document.getElementById('dn').onclick=e=>{isNight=!isNight;e.target.textContent=isNight?'☀️ Passer en jour':'🌙 Passer en nuit'};document.getElementById('export').onclick=()=>{let a=document.createElement('a');a.href=c.toDataURL();a.download=vid+(isNight?'_nuit':'_jour')+'.png';a.click()};document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'⏸ Pause nuages':'▶ Animer nuages'};document.getElementById('speed').oninput=e=>{speed=+e.target.value;document.getElementById('spd').textContent=speed+'px/s'};const P=D.manifest.cloud_period;function draw(im,x,y){if(im.complete&&im.naturalWidth)ctx.drawImage(im,x,y)}function render(t){const dt=Math.min(100,t-(last||t));last=t;if(playing)off=(off+speed*dt/1000)%P;document.getElementById('off').textContent='décalage '+Math.round(off)+'px / '+P;document.getElementById('status').textContent=D.variants[vid].title+(isNight?' · nuit':' · jour');ctx.clearRect(0,0,768,512);const s=isNight?'_nuit':'_jour';if(vis.ciel)draw(isNight?IM['02_ciel_nuit']:IM['01_ciel_jour'],0,0);if(vis.nuages){const cl=isNight?IM['06_nuages_wrap_nuit']:IM['05_nuages_wrap_jour'];for(let x=-off;x<768;x+=P)draw(cl,x,0)}if(vis.mer)draw(isNight?IM['04_mer_nuit']:IM['03_mer_jour'],0,0);if(vis.falaise)draw(isNight?IM[vid+'_n']:IM[vid+'_j'],0,0);requestAnimationFrame(render)}requestAnimationFrame(render);</script></html>'''
(R / 'apercu_falaises_proches_metano_v1.html').write_text(h.replace('__DATA__', json.dumps(data)), encoding='utf8')
print('gallery written')
